solution.solution.c:
long long sum_to(int n)
{
    long long total = 0;
    for (int i = 1; i <= n; i++) {
        total += i;
    }
    return total;
}

int count_digits(long long n)
{
    int digits = 1;
    while (n >= 10 || n <= -10) {
        n /= 10;
        digits++;
    }
    return digits;
}

int is_prime(int n)
{
    if (n < 2) return 0;
    for (int d = 2; (long long)d * d <= n; d++) {
        if (n % d == 0) return 0;
    }
    return 1;
}

int gcd(int a, int b)
{
    while (b != 0) {
        int rest = a % b;
        a = b;
        b = rest;
    }
    return a;
}

unitTests:
TEST("sum to n") { CHECK_EQ(sum_to(1), 1LL); CHECK_EQ(sum_to(10), 55LL); CHECK_EQ(sum_to(100000), 5000050000LL); CHECK_EQ(sum_to(0), 0LL); CHECK_EQ(sum_to(-5), 0LL); }
TEST("counting digits") { CHECK_EQ(count_digits(0), 1); CHECK_EQ(count_digits(7), 1); CHECK_EQ(count_digits(10), 2); CHECK_EQ(count_digits(99999), 5); CHECK_EQ(count_digits(-1234), 4); CHECK_EQ(count_digits(1000000000000LL), 13); }
TEST("primes") { CHECK(is_prime(2)); CHECK(is_prime(3)); CHECK(is_prime(97)); CHECK(is_prime(7919)); CHECK(!is_prime(1)); CHECK(!is_prime(0)); CHECK(!is_prime(-7)); CHECK(!is_prime(91)); CHECK(!is_prime(7917)); }
TEST("greatest common divisor") { CHECK_EQ(gcd(12, 18), 6); CHECK_EQ(gcd(18, 12), 6); CHECK_EQ(gcd(17, 5), 1); CHECK_EQ(gcd(100, 25), 25); CHECK_EQ(gcd(7, 7), 7); }

